namespace Aw.Kernel.Ids;

/// <summary>
/// A strongly typed id or constrained value (spec §4b.3, decision R9). Vogen value objects declared with
/// 'Conversions.None' satisfy it through their generated 'TryFrom' and 'Value' members, so the Kernel's converters
/// and the id port work with any package's ids while the Kernel stays free of Vogen (BCL only, spec §4b.1).
/// <see cref="IParsable{TSelf}"/> (also generated by Vogen, and validating) lets minimal-API routes bind ids through
/// the request-delegate generator; text the type refuses is a 400.
/// </summary>
/// <typeparam name="TSelf">The id type.</typeparam>
/// <typeparam name="TValue">The primitive it wraps.</typeparam>
public interface ITypedId<TSelf, TValue> : IParsable<TSelf>
    where TSelf : struct, ITypedId<TSelf, TValue>
{
    /// <summary>The wrapped primitive, as written to JSON and bound to SQL parameters.</summary>
    public TValue Value { get; }

    /// <summary>Wraps <paramref name="value"/> when the type accepts it.</summary>
    /// <param name="value">The primitive.</param>
    /// <param name="id">The id, when accepted.</param>
    /// <returns>Whether the type accepts the value.</returns>
    public static abstract bool TryFrom(TValue value, out TSelf id);
}
